export const meta = {
  name: 'catchup-plan-update',
  description: 'Opus planners update the catch-up roadmap, affected phase docs and prompts after catalogue changes',
  phases: [
    { title: 'Outline', detail: 'architect update, coverage check, critic, revision', model: 'opus' },
    { title: 'Detail', detail: 'one writer + one reviewer per affected phase', model: 'opus' },
  ],
}

/*
 * args (built by the update-build-plan skill from tools/plan-state.mjs):
 *   root         repo root
 *   baseline     the plan's current catalogue commit (plan.json "commit")
 *   commit       the catalogue commit the plan is being brought up to
 *   today        YYYY-MM-DD
 *   units        tools/units.json after the re-grade (every gap, DM and RV id to plan)
 *   oldPhases    [{num, title, file, covers}] from plan.json before this run
 *   builtPhases  phase numbers already built (frozen: never rewritten, follow-up goes to later phases)
 *   changeNotes  short text: what changed and where the change logs are (paths), from the skill's scoping
 */
const ROOT = args.root
const CU = 'docs/prototype-build/catch-up'
const CAT = 'requirements-board/requirements'
const O = 'opus'
const UNITS = args.units
const OLD = args.oldPhases
const BUILT = new Set(args.builtPhases || [])
const B7 = args.baseline.slice(0, 7)
const C7 = args.commit.slice(0, 7)

const CTX = `You are one agent updating the "requirements catch-up" build plan of the Anaesthesia Associates (AA) prototype.
- Repo root: ${ROOT} (use absolute paths; folder names contain spaces).
- The prototype (aa-prototype/) is a React demo over a fake in-browser backend, shown in live vendor workshops. The requirements catalogue ("${CAT}/stories/<ID>.md", questions in "${CAT}/questions/OQ-nn.md", evidence in "${CAT}/notes/", model in "requirements-board/requirements/domain-model.md") is the source of truth.
- The catch-up plan in "${CU}/" was built against catalogue commit ${B7}: README.md, ROADMAP.md (owner decisions D1 to D11 mapped to OQs, phase table, open-questions table, parked list), plan.json, phases/phase-NN-<slug>.md and .prompt.md, index.html (generated by tools/build-index.mjs), and the verified gap analysis (gaps.json, GAP-ANALYSIS.md, epics/EP-nn.md, analysis/ with the prototype maps, domain-model-delta.md and reverse-check.md).
- The catalogue has moved to commit ${C7}, and the changed items have already been re-graded against the prototype (gaps.json and GAP-ANALYSIS.md are current). What changed: ${args.changeNotes}
  See it yourself with: node ${CU}/tools/plan-state.mjs --to ${C7} --diff <IDs> (rename-aware: the catalogue moved after some baselines, so never a plain git diff of its folder)
- Phases already built (frozen; never rewrite them, put follow-up work in a later phase): ${[...BUILT].join(', ') || 'none'}.
- The product owner's standing rules: Future and Retired items are excluded; anything not demoable through normal use gets a screen-contextual demo-trigger button in the harness bar (plus the PWA equivalent); phases are numbered upward, each sized for one focused Claude Code session (two at most) with one coherent deliverable, leaving the app green and demoable; phases run back to back with no owner review between them (ROADMAP.md "Owner review: agents test themselves": no plan-approval stop, the agent runs the manual test checklist itself in the running app, "ask the owner" becomes a built default logged on the phase's "For the owner's review" list, and the owner reviews once after the last phase).
- Project rules are in CLAUDE.md (already loaded). Only write the files you are told to write. Never commit.`

const PHASE = {
  type: 'object',
  properties: {
    num: { type: 'string' }, slug: { type: 'string' }, title: { type: 'string' }, track: { type: 'string' },
    goal: { type: 'string' }, delivers: { type: 'string' },
    depends_on: { type: 'array', items: { type: 'string' } }, est_sessions: { type: 'string' },
    covers: { type: 'array', items: { type: 'string' } }, demo_triggers: { type: 'array', items: { type: 'string' } },
    blocked_by_oqs: { type: 'array', items: { type: 'string' } }, risks: { type: 'string' },
  },
  required: ['num', 'slug', 'title', 'track', 'goal', 'delivers', 'depends_on', 'est_sessions', 'covers', 'demo_triggers', 'blocked_by_oqs', 'risks'],
}
const OUTLINE = {
  type: 'object',
  properties: {
    phases: { type: 'array', items: PHASE },
    parked: { type: 'array', items: { type: 'object', properties: { id: { type: 'string' }, reason: { type: 'string' } }, required: ['id', 'reason'] } },
    sequencing_rules: { type: 'string' },
    milestones: { type: 'array', items: { type: 'object', properties: { after: { type: 'string' }, can_show: { type: 'string' } }, required: ['after', 'can_show'] } },
    affected: { type: 'array', items: { type: 'object', properties: { num: { type: 'string' }, reason: { type: 'string' } }, required: ['num', 'reason'] }, description: 'Every unbuilt phase whose doc must change: changed covered items, answered decisions or OQs it planned defaults for, new or removed work, dependency or scope shifts.' },
  },
  required: ['phases', 'parked', 'sequencing_rules', 'milestones', 'affected'],
}

const coverage = o => {
  const seen = new Map()
  for (const p of o.phases) for (const id of p.covers) seen.set(id, [...(seen.get(id) || []), p.num])
  for (const x of o.parked) seen.set(x.id, [...(seen.get(x.id) || []), 'parked'])
  const missing = UNITS.filter(u => !seen.has(u))
  const dupes = [...seen].filter(([, v]) => v.length > 1).map(([k, v]) => `${k} in ${v.join(' + ')}`)
  const unknown = [...seen.keys()].filter(k => !UNITS.includes(k))
  return { ok: !missing.length && !dupes.length, missing, dupes, unknown }
}
const covText = c => `Missing (in no phase and not parked): ${c.missing.join(', ') || 'none'}\nIn more than one place: ${c.dupes.join('; ') || 'none'}\nNo longer units (now Matches, Retired or Future: remove them from covers, or keep them only on a built phase): ${c.unknown.join(', ') || 'none'}`

const ROADMAP_FILE = `${ROOT}/${CU}/ROADMAP.md`
const guidance = `How to update:
- Read ROADMAP.md, plan.json, the change logs and changed catalogue items (plan-state --diff above), and the re-graded entries in gaps.json for every changed item (use node or jq; it is large).
- Keep the plan stable: change only what the catalogue changes require. Keep phase numbers of existing phases; add new phases at the end of their track with the next free number (or a letter suffix such as 27a if order matters more than numbering).
- Answered questions and owner decisions: the phase that planned a default now builds the answer; record the answer in ROADMAP's decisions table and drop the default; remove answered OQs from blocked_by_oqs and the open-questions table.
- New gaps go to the best-fitting unbuilt phase or a new phase. Items now Matches, Retired or Future leave covers (note any code that must be removed in that phase's work).
- Re-check dependencies, ordering, estimates, milestones and the parked list.
- Every unit below must be in exactly one phase's covers or parked.
Units (${UNITS.length}): ${UNITS.join(', ')}
Current phases and covers (JSON): ${JSON.stringify(OLD)}`
const roadmapSpec = `Update "${ROADMAP_FILE}" to match the outline (intro counts, decisions table, track diagram, phase table, open-questions table, sequencing rules, milestones, parked list), keeping its style. Replace the baseline commit ${B7} with ${C7} in it.`

phase('Outline')
let outline = await agent(`${CTX}

TASK: you are the lead architect. Update the catch-up phase outline for the catalogue changes.

${guidance}

Then ${roadmapSpec}
Return the full updated outline (all phases, built ones unchanged) and the affected phases with reasons.`, { label: 'architect:update', phase: 'Outline', model: O, effort: 'xhigh', schema: OUTLINE })

for (let i = 0; i < 2; i++) {
  const c = coverage(outline)
  log(`coverage: ${c.missing.length} missing, ${c.dupes.length} duplicated, ${c.unknown.length} stale`)
  if (c.ok && !c.unknown.filter(u => !outline.phases.some(p => BUILT.has(p.num) && p.covers.includes(u))).length) break
  outline = await agent(`${CTX}

TASK: fix coverage in this updated outline. Every unit must be in exactly one phase's covers or parked; stale ids leave unbuilt phases. Keep everything else unchanged, and keep "affected" complete (add any phase you change).
${covText(c)}

Outline (JSON):
${JSON.stringify(outline)}

Then update "${ROADMAP_FILE}" to match. Return the fixed outline.`, { label: `coverage-fix-${i + 1}`, phase: 'Outline', model: O, effort: 'high', schema: OUTLINE })
}

const critique = await agent(`${CTX}

TASK: independent critic of the updated outline below (also in ${ROADMAP_FILE}). Read the catalogue diff, the change logs and the re-graded gaps yourself. Challenge: did every change reach a phase? Are answered decisions built as answered, not as the old default? Is any newly placed work in the wrong phase or before its dependencies? Is any phase now too big (more than two sessions) or empty? Is "affected" complete? Built phases untouched? Return "revise" only for material issues.

Outline (JSON):
${JSON.stringify(outline)}`, {
  label: 'critic', phase: 'Outline', model: O, effort: 'high',
  schema: { type: 'object', properties: { verdict: { type: 'string', enum: ['ok', 'revise'] }, issues: { type: 'array', items: { type: 'object', properties: { severity: { type: 'string', enum: ['major', 'minor'] }, issue: { type: 'string' }, suggestion: { type: 'string' } }, required: ['severity', 'issue', 'suggestion'] } } }, required: ['verdict', 'issues'] },
})
if (critique && critique.verdict === 'revise') {
  log(`critic: revise (${critique.issues.filter(i => i.severity === 'major').length} major)`)
  const revised = await agent(`${CTX}

TASK: lead architect: revise the updated outline in response to the critic. Accept what is right, reject what is not. Keep coverage complete and "affected" complete.

${guidance}

Critic's issues (JSON): ${JSON.stringify(critique.issues)}
Current outline (JSON): ${JSON.stringify(outline)}

Then ${roadmapSpec}
Return the revised outline.`, { label: 'architect:revise', phase: 'Outline', model: O, effort: 'xhigh', schema: OUTLINE })
  if (revised) outline = revised
}
const finalCov = coverage(outline)
log(`outline: ${outline.phases.length} phases; coverage ${finalCov.ok ? 'complete' : covText(finalCov)}`)

const oldByNum = new Map(OLD.map(p => [p.num, p]))
const sameCovers = (a, b) => a.length === b.length && a.every(x => b.includes(x))
const affectedNums = new Set(outline.affected.map(a => a.num))
for (const p of outline.phases) {
  const old = oldByNum.get(p.num)
  if (!old || !sameCovers(old.covers, p.covers)) affectedNums.add(p.num)
}
const work = outline.phases.filter(p => affectedNums.has(p.num) && !BUILT.has(p.num))
const reasonOf = num => (outline.affected.find(a => a.num === num) || {}).reason || (oldByNum.has(num) ? 'its covered items changed' : 'new phase')
log(`phases to update: ${work.map(p => p.num).join(', ') || 'none'}`)

const outlineSummary = outline.phases.map(p => `${p.num} ${p.title} (after ${p.depends_on.join(', ') || 'none'})${BUILT.has(p.num) ? ' [BUILT]' : ''}: ${p.delivers}`).join('\n')
const fileOf = p => (oldByNum.get(p.num) && oldByNum.get(p.num).file) || `phases/phase-${p.num}-${p.slug}.md`
const promptOf = p => fileOf(p).replace(/\.md$/, '.prompt.md')

const DETAIL = {
  type: 'object',
  properties: { num: { type: 'string' }, goal_short: { type: 'string' }, checks: { type: 'array', items: { type: 'string' } }, changes: { type: 'string' } },
  required: ['num', 'goal_short', 'checks', 'changes'],
}

phase('Detail')
const details = await pipeline(
  work,
  p => {
    const isNew = !oldByNum.has(p.num)
    return agent(`${CTX}

TASK: ${isNew ? 'write' : 'update'} the plan for catch-up Phase ${p.num} "${p.title}" and its kick-off prompt. Why: ${reasonOf(p.num)}.

The full outline (other affected phases are being updated in parallel; stay inside this phase's scope):
${outlineSummary}
Sequencing rules: ${outline.sequencing_rules}
This phase (JSON): ${JSON.stringify(p)}

Files: "${ROOT}/${CU}/${fileOf(p)}" and "${ROOT}/${CU}/${promptOf(p)}".
${isNew
  ? `Write both in the house style of the existing catch-up phase docs (read two neighbouring ones and their prompts first). Sections: title, Requirements covered (links to catalogue files, relative ../../../../requirements-board/requirements/stories/<ID>.md; DM/RV ids to ../analysis/), Depends on, Estimated, Goal, Before you start (drift check against ${C7}; open OQs with safe interim), Reference, Work items (concrete, naming real files, store actions and seed structures), Demo triggers, Out of scope, Manual test checklist, Demo guide updates, Catalogue screenshots (the standing step in ${CU}/ROADMAP.md "Catalogue screenshots": one table row per item \`node ${CU}/tools/recipe-status.mjs ${p.num}\` lists, with its recipe now and what it must be when the phase is done; the recipes this phase breaks; the ATLAS.md sections to update), Adversarial review steer, PROGRESS.md updates. The prompt's "When done:" runs the catalogue screenshot step (recipes, a full npm run capture with no failed recipe, npm run verify:board). The prompt file holds only the kick-off prompt text. Never edit capture recipes, catalogue images or capture/REPORT.md: the build phase does that. If the phase touches UI, the prompt's "While working:" list opens with the frontend-design bullet (ROADMAP.md "Front-end design"; copy it from a neighbouring prompt).`
  : `Edit both in place. Read the current doc and prompt, then for every covered item that changed (node ${CU}/tools/plan-state.mjs --to ${C7} --diff <its ID>, and its re-graded gaps.json entry) and every answered decision or OQ this phase depended on: update Requirements covered, Goal, Before you start, Work items, Demo triggers, Manual test checklist, Demo guide updates, Catalogue screenshots (one row per item \`node ${CU}/tools/recipe-status.mjs ${p.num}\` lists; add rows for items that joined, drop rows for items that left, and re-state what each recipe must show when the phase is done), reviewer steer and the prompt. Build answers instead of defaults and drop "provisional" labelling. Never edit capture recipes, catalogue images or capture/REPORT.md: the build phase does that. If the phase touches UI, the prompt's "While working:" list opens with the frontend-design bullet (ROADMAP.md "Front-end design"; copy it from a neighbouring prompt). Remove work for items that left this phase; add work for items that joined it. Replace the baseline ${B7} with ${C7}.`}
Read the prototype code you name. Return goal_short, checks (3 or 4 "what to check when it's done" bullets) and changes "".`, { label: `${isNew ? 'write' : 'update'}:${p.num}`, phase: 'Detail', model: O, effort: 'high', schema: DETAIL })
  },
  (draft, p) => agent(`${CTX}

TASK: independent reviewer of catch-up Phase ${p.num} "${p.title}" after its update. Files: "${ROOT}/${CU}/${fileOf(p)}" and "${ROOT}/${CU}/${promptOf(p)}". Fix problems in place.
Outline:
${outlineSummary}
This phase (JSON): ${JSON.stringify(p)}
Check, reading the sources yourself: (1) every covered unit's current catalogue text, acceptance criteria and gaps.json entry is addressed; nothing from a removed or changed requirement survives; (2) answered questions and decisions are built as answered; (3) named files, components and store actions exist or are marked new; (4) scope fits neighbours and dependencies; (5) CLAUDE.md rules, screen-contextual demo triggers, demo-guide mirroring; (6) the prompt is right for a fresh agent and its drift-check baseline is ${C7}; (7) the "## Catalogue screenshots" section names every item \`node ${CU}/tools/recipe-status.mjs ${p.num}\` lists with what its recipe must show, and the prompt runs npm run capture; (8) a phase that touches UI has the frontend-design bullet in "While working:".
Return goal_short, checks and changes (what you changed, or "none").`, { label: `review:${p.num}`, phase: 'Detail', model: O, effort: 'high', schema: DETAIL }).then(r => r || draft),
)
const det = details.filter(Boolean)
log(`phase docs: ${det.length}/${work.length} updated and reviewed`)

// Publishing (plan.json, baseline, index.html) is done after the run by tools/apply-plan-update.mjs,
// which rebuilds plan.json exactly from this run's journal, then a final consistency check.
return { phases: outline.phases.length, updated: work.map(p => `${p.num} ${p.title}: ${reasonOf(p.num)}`), reviewed: det.map(d => `${d.num}: ${String(d.changes).slice(0, 200)}`), coverage: finalCov, critic: critique ? critique.verdict : null }
